.contact-map-section h2 {
  margin-bottom: var(--spacing-md);
}

.contact-map-section .text-muted {
  margin-bottom: var(--spacing-lg);
  max-width: 600px;
}

.map-placeholder {
  border-radius: var(--radius);
  overflow: hidden;
  box-shadow: 0 8px 20px rgba(0, 0, 0, 0.1);
  margin-top: var(--spacing-lg);
}

.map-placeholder img {
  width: 100%;
  height: auto;
  display: block;
