@media (max-width: 600px) {
  .contact-layout {
    grid-template-columns: 1fr;
    gap: var(--spacing-lg);
  }

  .contact-form-fields {
    padding: var(--spacing-md);
  }

  .form-group {
    margin-bottom: var(--spacing-md);
  }

  .contact-form-wrapper h2,
  .contact-info-wrapper h2 {
    font-size: 1.5rem;
  }

  .info-card {
    padding: var(--spacing-md);
    margin-bottom: var(--spacing-md);
  }

  .contact-hero {
    padding: var(--spacing-lg) 0;
  }
}

@media (min-width: 601px) {
  .contact-layout {
    grid-template-columns: 1fr 1fr;
  }

  .contact-form-fields {
    position: sticky;
    top: 120px;
  }
}

final.css:
:root {
  --color-primary: #2c3e50;
  --color-primary-dark: #1a2332;
  --color-accent: #d4847a;
  --color-accent-dark: #a85c50;
  --color-accent-on-dark: #f5d9d5;
  --color-neutral-light: #f8f7f6;
  --color-neutral-medium: #e8e6e4;
  --color-text: #2c3e50;
  --color-text-light: #6b7280;
  --color-success: #52a375;
  --color-link: #a85c50;
  --color-border: #d9d6d2;
  --font-serif: Georgia, "Times New Roman", serif;
  --font-sans: "Segoe UI", Roboto, "Helvetica Neue", sans-serif;
  --spacing-xs: 0.5rem;
  --spacing-sm: 1rem;
  --spacing-md: 1.5rem;
  --spacing-lg: 2rem;
  --spacing-xl: 3rem;
  --spacing-2xl: 4rem;
  --radius: 6px;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-sans);
  color: var(--color-text);
  background-color: #fff;
  line-height: 1.6;
  font-size: 16px;
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-serif);
  font-weight: 700;
  margin-bottom: var(--spacing-md);
  color: var(--color-primary);
}

h1 {
  font-size: clamp(2rem, 5vw, 3.5rem);
  line-height: 1.2;
}

h2 {
  font-size: clamp(1.75rem, 4vw, 2.5rem);
  line-height: 1.3;
}

h3 {
  font-size: clamp(1.25rem, 3vw, 1.75rem);
}

h4 {
  font-size: 1.25rem;
}

p {
  margin-bottom: var(--spacing-md);
  color: var(--color-text);
}

a {
  color: var(--color-link);
  text-decoration: none;
  transition: color 0.3s ease;
}

a:hover {
  color: var(--color-primary);
  text-decoration: underline;
}

a:focus {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
  border-radius: 2px;
}

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 var(--spacing-md);
}

.site-header {
  background-color: #fff;
  border-bottom: 1px solid var(--color-border);
  padding: var(--spacing-md) 0;
  position: sticky;
  top: 0;
  z-index: 100;
}

.site-header .container {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.logo {
  font-family: Georgia, "Times New Roman", serif;
  font-size: 1.3rem;
  font-weight: 700;
  letter-spacing: 0.2em;
  color: var(--color-primary-dark);
  text-decoration: none;
  border-top: 3px double var(--color-accent-dark);
  border-bottom: 3px double var(--color-accent-dark);
  padding: 0.3rem 0.6rem;
  white-space: nowrap;
  transition: color 0.3s ease;
}

.logo:hover {
  color: var(--color-accent-dark);
}

.logo:focus {
  outline: 3px solid var(--color-accent);
  outline-offset: 4px;
}

.site-header nav {
  display: flex;
  gap: var(--spacing-lg);
  flex-wrap: wrap;
}

.site-header nav a {
  color: var(--color-text);
  text-decoration: none;
  font-weight: 500;
  padding: 0.5rem 0;
  border-bottom: 2px solid transparent;
  transition: border-color 0.3s ease, color 0.3s ease;
}

.site-header nav a:hover {
  color: var(--color-accent-dark);
  border-bottom-color: var(--color-accent-dark);
}

.site-header nav a:focus {
  outline: 3px solid var(--color-accent);
  outline-offset: 6px;
  border-radius: 2px;
}

.site-footer {
  background-color: var(--color-primary);
  color: var(--color-accent-on-dark);
  padding: var(--spacing-2xl) 0 var(--spacing-lg);
  margin-top: var(--spacing-2xl);
}

.site-footer .container {
  margin-bottom: var(--spacing-lg);
}

.footer-content {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: var(--spacing-lg);
  margin-bottom: var(--spacing-lg);
}

.footer-content div {
  font-size: 0.95rem;
}

.footer-content strong {
  color: #fff;
  display: block;
  margin-bottom: var(--spacing-xs);
}

.footer-content p {
  margin-bottom: var(--spacing-sm);
  color: var(--color-accent-on-dark);
}

.footer-content a {
  color: var(--color-accent-on-dark);
}

.footer-content a:hover {
  color: #fff;
}

.copyright {
  text-align: center;
  padding-top: var(--spacing-lg);
  border-top: 1px solid rgba(245, 217, 213, 0.2);
  font-size: 0.9rem;
  color: var(--color-accent-on-dark);
}

/* Buttons */
button, .btn {
  display: inline-block;
  padding: 0.875rem 1.75rem;
  min-height: 44px;
  background-color: var(--color-accent-dark);
  color: #fff;
  border: none;
  border-radius: var(--radius);
  font-family: var(--font-sans);
  font-size: 1rem;
  font-weight: 600;
  text-decoration: none;
  cursor: pointer;
  transition: background-color 0.3s ease, transform 0.2s ease;
  text-align: center;
  vertical-align: middle;
}

button:hover, .btn:hover {
  background-color: var(--color-primary-dark);
  transform: translateY(-2px);
}

button:focus, .btn:focus {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
}

button:active, .btn:active {
  transform: translateY(0);
}

/* Form Elements */
label {
  display: block;
  margin-bottom: var(--spacing-xs);
  font-weight: 500;
  color: var(--color-text);
}

input[type="text"],
input[type="email"],
input[type="phone"],
input[type="date"],
input[type="textarea"],
textarea,
select {
  width: 100%;
  padding: 0.875rem;
  min-height: 44px;
  border: 2px solid var(--color-border);
  border-radius: var(--radius);
  font-family: var(--font-sans);
  font-size: 1rem;
  color: var(--color-text);
  background-color: #fff;
  transition: border-color 0.3s ease, box-shadow 0.3s ease;
}

input[type="text"]:focus,
input[type="email"]:focus,
input[type="phone"]:focus,
input[type="date"]:focus,
textarea:focus,
select:focus {
  border-color: var(--color-accent-dark);
  box-shadow: 0 0 0 3px rgba(168, 92, 80, 0.1);
  outline: none;
}

textarea {
  resize: vertical;
  min-height: 150px;
}

/* Cards */
.card {
  background-color: #fff;
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  padding: var(--spacing-lg);
  transition: box-shadow 0.3s ease, transform 0.3s ease;
}

.card:hover {
  box-shadow: 0 8px 16px rgba(0, 0, 0, 0.08);
  transform: translateY(-4px);
}

/* Grid Helpers */
.grid-2 {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: var(--spacing-lg);
}

.grid-3 {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: var(--spacing-lg);
}

.grid-4 {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: var(--spacing-lg);
}

/* Section Spacing */
section {
  padding: var(--spacing-2xl) 0;
}

section:first-of-type {
  padding-top: var(--spacing-xl);
}

/* Images */
img {
  max-width: 100%;
  height: auto;
  display: block;
}

/* Utility Classes */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.text-center {
  text-align: center;
}

.text-muted {
  color: var(--color-text-light);
}

/* Mobile Breakpoint */
@media (max-width: 600px) {
  .site-header .container {
    flex-direction: column;
    gap: var(--spacing-sm);
    align-items: flex-start;
  }

  .logo {
    font-size: clamp(1rem, 5vw, 1.3rem);
    padding: 0.25rem 0.4rem;
  }

  .site-header nav {
    width: 100%;
    gap: var(--spacing-md);
    flex-wrap: wrap;
  }

  .site-header nav a {
    font-size: 0.95rem;
  }

  h1 {
    font-size: 1.75rem;
  }

  h2 {
    font-size: 1.5rem;
  }

  h3 {
    font-size: 1.1rem;
  }

  .container {
    padding: 0 var(--spacing-sm);
  }

  section {
    padding: var(--spacing-lg) 0;
  }

  .grid-2,
  .grid-3,
  .grid-4 {
    grid-template-columns: 1fr;
    gap: var(--spacing-md);
  }

  .footer-content {
    grid-template-columns: 1fr;
  }

  button, .btn {
    width: 100%;
  }
}

/* Desktop Breakpoint */
@media (min-width: 601px) {
  body {
    font-size: 16px;
  }

  .site-header nav a {
    font-size: 0.95rem;
  }
}

/* Reduced Motion */
@media (prefers-reduced-motion: reduce) {
  * {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

